const items = $input.all();
const output = items.reduce((acc, item) => {
  const output = item.json.output;
  Object.keys(output).forEach((key) => {
    const value = output[key];
    const newKey = `${key}`;
    acc[newKey] = value;
  });
  return acc;
}, {});

return [{ json: output }];

